import{z as s,x as E,o as r,c as B,q as t,j as i,D as e,d as o,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"顶部抗反射 TARC","description":"","frontmatter":{"title":"顶部抗反射 TARC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tarc.md","filePath":"litho/tarc.md","lastUpdated":1791413859000}'),T={name:"litho/tarc.md"};function C(p,a,R,d,h,m){const A=E("Mermaid");return r(),B("div",null,[a[2]||(a[2]=t('<h1 id="顶部抗反射-tarc" tabindex="-1">顶部抗反射 TARC <a class="header-anchor" href="#顶部抗反射-tarc" aria-label="Permalink to &quot;顶部抗反射 TARC&quot;">​</a></h1><div class="epigraph"><p>BARC 压的是胶底往上的回波；TARC 压的是胶顶与空气（或水）那一界面。两头不是同一层膜的两个名字。</p><footer>—— Mack 对 TARC / 顶面反射与 swing 的区分；浸没面涂功能另见 Levinson</footer></div><p><a href="/litho/resist-thickness-selection">上一课</a>要求先压摆动振幅再选极值。缺口是：底面 BARC 之后，<strong>顶面 Fresnel</strong> 仍贡献 swing 与入射侧多次反射，有时还贡献光斑（flare）式的杂散。本课钉顶部抗反射涂层（TARC）。多层底部抗反射留给<a href="/litho/multilayer-barc">下一课</a>。CAR 的面涂挡胺、浸没防浸出，与 TARC 光学功能重叠但合同不同，本课只收光学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>胶顶 \\(n\\) 与空气（\\(\\approx 1\\)）或水（\\(\\approx 1.44\\)）失配，正入射反射已不可忽略，高 NA 更大。顶面反射使入射能量随胶厚摆动（上一课的「顶头」），并在胶内与底面回波形成更复杂的多光束。TARC 是一层（或两层）折射率与厚度选在减反条件附近的顶膜，把顶面有效 \\(|r_\\mathrm{top}|\\) 压下去。</p><p>缺口不是再选一次胶厚，而是：TARC 不替代 BARC。只涂 TARC、衬底仍亮，驻波节点还在；只做 BARC、顶面仍亮，swing 的能量项还在。浸没之后顶面失配减小，TARC 的光学动机变弱，面涂转为化学隔离——不要把浸没面涂自动叫成 TARC。</p><p><span class="marginnote">术语翻译：TARC（Top Anti-Reflective Coating）就是涂在光刻胶最上面的一层「增透膜」，原理和眼镜片上的镀膜一样——选好折射率和厚度，让顶面来回的两束反射光互相抵消，光就几乎全透进胶里，不再被弹回来打扰。</span></p><h3 id="与斑纹、缺陷" tabindex="-1">与斑纹、缺陷 <a class="header-anchor" href="#与斑纹、缺陷" aria-label="Permalink to &quot;与斑纹、缺陷&quot;">​</a></h3><p>顶面不平整或 TARC 涂覆不均，本身可以当弱相位屏。光学减反若引入颗粒或条纹，检测会报缺陷。选 TARC 要看轨道缺陷，不只看椭圆偏振仪上的 \\(|r|\\)。本课不写商品名。</p><p><span class="marginnote">TARC 通常要在曝光后、显影前去掉或可溶于显影液，以免挡溶解。厚度进入光学厚度预算，去掉之后最终浮雕不再含这层，但曝光时的 \\(I(z)\\) 已经按有 TARC 算过。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：在胶 \\(n\\)、入射介质 \\(n_0\\)、中心波长与主要 \\(\\theta\\) 上解减反（单层四分之一波一类，或双层）。高 NA 对角谱做平均，正入射最优不一定是浸没边缘光线最优。模拟必须把 TARC 算进薄膜矩阵，再决定胶厚工作点——顺序与上一课一致：TARC 改振幅与相位，极值位置会移。</p><p>计量：无 TARC / 有 TARC 的 swing 振幅对比。底面 BARC 不变时，振幅下降应主要来自顶头。若几乎不降，说明底面 \\(|r|\\) 仍主导，该去查 BARC 而不是加厚 TARC。</p>',13)),(r(),i(l,null,{default:e(()=>[n(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOP%5B%22%E8%83%B6%E9%A1%B6%20Fresnel%22%5D%20--%3E%20SW%5B%22swing%20%E8%83%BD%E9%87%8F%E9%A1%B9%22%5D%0A%20%20BOT%5B%22%E8%83%B6%E5%BA%95%20r%22%5D%20--%3E%20SW%0A%20%20TARC%5B%22TARC%20%E5%87%8F%E5%8F%8D%22%5D%20--%3E%20TOP%0A%20%20BARC%5B%22BARC%22%5D%20--%3E%20BOT%0A%20%20TARC%20--%3E%20CHEM%5B%22%E5%8B%BF%E4%B8%8E%E6%8C%A1%E8%83%BA%E9%9D%A2%E6%B6%82%E6%B7%B7%E5%90%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与矢量成像" tabindex="-1">与矢量成像 <a class="header-anchor" href="#与矢量成像" aria-label="Permalink to &quot;与矢量成像&quot;">​</a></h3><p>s/p 顶面系数不同，TARC 的减反对 TE/TM 不对称。密线若走 TE，TARC 优化应对准该偏振的角谱，而不是对准非偏振正入射。这是薄膜单元接到浸没矢量课的接口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>减反条件：从入射介质看进去的等效导纳匹配，顶面 \\(r_\\mathrm{top}\\to 0\\)，多次反射项消失，swing 振幅下降。残留的振荡便主要来自底面驻波；BARC 再把它掐掉，曲线才真正平。TARC 相位也会微移胶内波腹，侧壁波纹形状可略变，但压节点对比仍靠 BARC。</p><p><span class="marginnote">数字实例：单层 TARC 的经典厚度是四分之一波长，\\(d=\\lambda/(4n_\\mathrm{TARC})\\)。取 193 nm、\\(n_\\mathrm{TARC}\\approx1.6\\)，得 \\(d\\approx30\\) nm——一层比胶本身薄一个量级的膜，就足以让两束顶面反射相位差半圈而抵消。</span></p>',5)),(r(),i(l,null,{default:e(()=>[n(A,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B0%84%E5%85%89%E6%89%93%E5%88%B0%E9%A1%B6%E9%9D%A2%22%5D%20--%3E%20R1%5B%22%E7%A9%BA%E6%B0%94%2FTARC%20%E7%95%8C%E9%9D%A2%E5%8F%8D%E5%B0%84%20r1%22%5D%0A%20%20IN%20--%3E%20T2%5B%22%E9%80%8F%E8%BF%9B%20TARC%20%E8%B5%B0%20%CE%BB%2F4%22%5D%0A%20%20T2%20--%3E%20R2%5B%22TARC%2F%E8%83%B6%20%E7%95%8C%E9%9D%A2%E5%8F%8D%E5%B0%84%20r2%22%5D%0A%20%20R2%20--%3E%20T4%5B%22%E8%BF%94%E5%9B%9E%E5%86%8D%E8%B5%B0%20%CE%BB%2F4%20%E7%9B%B8%E4%BD%8D%E5%85%B1%E8%BD%AC%E5%8D%8A%E5%9C%88%22%5D%0A%20%20T4%20--%3E%20CAN%5B%22%E4%B8%8E%20r1%20%E5%8F%8D%E7%9B%B8%20%E7%9B%B8%E4%BA%92%E6%8A%B5%E6%B6%88%22%5D%0A%20%20CAN%20--%3E%20OUT%5B%22%E9%A1%B6%E9%9D%A2%E6%9C%89%E6%95%88%20r_top%20%E8%B6%8B%E4%BA%8E%E9%9B%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：初学者容易以为浸没的水本身就算 TARC——水（\\(n\\approx1.44\\)）确实让顶面失配变小，但它是外部介质，不是一层可控的膜；浸没机的顶面涂层真正要干的活是挡胺、防浸出这些化学隔离。把两者混为一谈，会把光学设计和化学合同都写错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>i 线 / KrF / 干式 ArF 上 TARC 光学动机强；浸没 ArF 上光学动机弱、化学面涂动机强；EUV 顶面是真空，另有出气与盖层，不能抄 DUV TARC 四分之一波。禁止把未公开的「TARC 降几纳米 swing」当普遍数。也不要把 TARC 写成分辨率增强：它不改光瞳截止。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TARC 减顶面反射，BARC 减底面反射，分工不可吞并。</li><li>浸没面涂主要是化学隔离，不要自动等于 TARC。</li><li>加 TARC 后必须重选胶厚工作点。</li><li>高 NA 按角谱与偏振优化，不正入射一张表。</li><li>下一课：底部用多层才能在角度上压 \\(|r|\\)。</li><li>出处：Mack；Levinson；Born &amp; Wolf。</li></ul>',5))])}const D=s(T,[["render",C]]);export{c as __pageData,D as default};
